-- I18N-2: seed English UI source without changing human translations.

on conflict (key) do update
set context = excluded.context,
    description = excluded.description,
    english_source = excluded.english_source,
    updated_at = case
      when public.translation_entries.context is distinct from excluded.context
        or public.translation_entries.description is distinct from excluded.description
        or public.translation_entries.english_source is distinct from excluded.english_source
      then now()
      else public.translation_entries.updated_at
    end;

create function public.get_application_translation_catalog()
returns table (
  key text,
  english text,
  spanish text,
  french text,
  turkish text
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    entry.key,
    entry.english_source,
    coalesce(max(value.value) filter (where value.language_code = 'es'), ''),
    coalesce(max(value.value) filter (where value.language_code = 'fr'), ''),
    coalesce(max(value.value) filter (where value.language_code = 'tr'), '')
  from public.translation_entries as entry
  left join public.translation_values as value
    on value.translation_key = entry.key
  where entry.email_template_type is null
  group by entry.key
  order by entry.key;
$$;

revoke all on function public.get_application_translation_catalog() from public;
revoke all on function public.get_application_translation_catalog() from anon;
revoke all on function public.get_application_translation_catalog() from authenticated;
grant execute on function public.get_application_translation_catalog() to anon, authenticated;

comment on function public.get_application_translation_catalog() is
  'Read-only application catalog. Returns source and translated copy only; translation administration metadata remains protected.';
